const int TRIG = 9;
const int ECHO = 10;
const int BRAKE = 13;
unsigned long lastPrint = 0;

float ping() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);
  return us / 58.0;   // 0 when nothing came back within 30 ms
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BRAKE, OUTPUT);
  Serial.println("bumper: brakes under 20 cm");
}

void loop() {
  float cm = ping();
  bool brake = cm > 0 && cm < 20;
  digitalWrite(BRAKE, brake ? HIGH : LOW);
  if (millis() - lastPrint >= 1000) {
    lastPrint = millis();
    Serial.print(cm, 2);
    Serial.println(brake ? " cm BRAKE" : " cm");
  }
  delay(60);
}

